// Web-only tests: run with `flutter test --platform chrome [--wasm]`.
//
// `test/sqlite3.wasm` and `test/sqflite_sw.js` must exist (generated by
// `dart run sqflite_common_ffi_web:setup --dir test`): the test directory is
// served at the root of the test page.
@TestOn('browser')
library;

import 'package:flutter/foundation.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:remote_caching/remote_caching.dart';
import 'package:sqflite_common_ffi_web/sqflite_ffi_web.dart';

import 'helpers/platform_helpers.dart';

void main() {
  final cache = RemoteCaching.instance;

  tearDown(() async {
    await cache.dispose();
  });

  test('runs on the web', () {
    expect(kIsWeb, isTrue);
  });

  test('default factory (shared worker + IndexedDB) stores the database '
      'under the given virtual folder', () async {
    final folder = uniqueDatabasePath('layout');
    await cache.init(databasePath: folder);
    await cache.call<String>(
      'k',
      remote: () async => 'v',
      fromJson: (json) => json! as String,
    );
    await cache.dispose();

    // Open the same file directly with the default web factory.
    final db = await databaseFactoryFfiWeb.openDatabase(
      '$folder/remote_caching.db',
    );
    try {
      final rows = await db.query('cache');
      expect(rows, hasLength(1));
      expect(rows.single['key'], 'k');
      expect(rows.single['data'], '"v"');
      expect(rows.single['expires_at'], isA<int>());
    } finally {
      await db.close();
    }
    expect(
      await databaseFactoryFfiWeb.databaseExists('$folder/remote_caching.db'),
      isTrue,
    );
  });

  test('default location is remote_caching.db at the IndexedDB root', () async {
    await cache.init();
    await cache.call<String>(
      'root_key',
      remote: () async => 'v',
      fromJson: (json) => json! as String,
    );
    await cache.dispose();
    expect(
      await databaseFactoryFfiWeb.databaseExists('/remote_caching.db'),
      isTrue,
    );
    await cache.init();
    await cache.clearCache();
  });

  test('the in-memory database is not written to IndexedDB', () async {
    await cache.init(databasePath: getInMemoryDatabasePath());
    await cache.call<String>(
      'mem',
      remote: () async => 'v',
      fromJson: (json) => json! as String,
    );
    expect(await cache.isCached('mem'), isTrue);
  });
}
